3	// Taxonomy: dynamic squads + tag definitions.
4	// Single source of truth = JSON files in ~/.claude/org/.
5	// Reads cached for perf; writes invalidate cache + emit SSE.
6	
7	const fs = require('fs');
8	const path = require('path');
9	const os = require('os');
10	
11	const HOME = os.homedir();
12	const ORG_DIR = path.join(HOME, '.claude', 'org');
13	const SQUADS_PATH = path.join(ORG_DIR, 'squads.json');
14	const TAGS_PATH = path.join(ORG_DIR, 'tag-taxonomy.json');
15	
16	let _squadsCache = null;
17	let _tagsCache = null;
18	
19	function readJson(filePath, fallback) {
20	  try {
21	    if (!fs.existsSync(filePath)) return fallback;
22	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
23	  } catch (err) {
24	    console.warn(`[taxonomy] failed to read ${filePath}: ${err.message}`);
25	    return fallback;
26	  }
27	}
28	
29	function atomicWrite(filePath, data) {
30	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
31	  const tmp = filePath + '.tmp';
32	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
33	  fs.renameSync(tmp, filePath);
34	}
35	
36	function loadSquads() {
37	  if (_squadsCache) return _squadsCache;
38	  const raw = readJson(SQUADS_PATH, { version: 1, squads: {} });
39	  _squadsCache = raw;
40	  return raw;
41	}
42	
43	function loadTags() {
44	  if (_tagsCache) return _tagsCache;
45	  const raw = readJson(TAGS_PATH, { version: 1, categories: {} });
46	  _tagsCache = raw;
47	  return raw;
48	}
49	
50	function invalidate() {
51	  _squadsCache = null;
52	  _tagsCache = null;
53	}
54	
55	function listSquads() {
56	  const data = loadSquads();
57	  return Object.values(data.squads || {});
58	}
59	
60	function listTagCategories() {
61	  const data = loadTags();
62	  return data.categories || {};
63	}
64	
65	function getTaxonomy() {
66	  return {
67	    squads: listSquads(),
68	    categories: listTagCategories(),
69	  };
70	}
71	
72	// ── Squads ─────────────────────────────────────────────────────────────────
73	
74	function addSquad(squad) {
75	  if (!squad?.id || typeof squad.id !== 'string') throw new Error('Squad id required');
76	  if (!squad.label) throw new Error('Squad label required');
77	  const id = squad.id.trim().toLowerCase().replace(/[^a-z0-9-]/g, '-');
78	  if (!id) throw new Error('Invalid squad id');
79	  const data = readJson(SQUADS_PATH, { version: 1, squads: {} });
80	  data.squads = data.squads || {};
81	  if (data.squads[id]) throw new Error(`Squad "${id}" already exists`);
82	  data.squads[id] = {
83	    id,
84	    label: squad.label.trim(),
85	    description: (squad.description || '').trim(),
86	    color: squad.color || '#6b7280',
87	    emoji: squad.emoji || '⚙️',
88	    members: Array.isArray(squad.members) ? squad.members : [],
89	  };
90	  data.updatedAt = new Date().toISOString();
91	  atomicWrite(SQUADS_PATH, data);
92	  invalidate();
93	  return data.squads[id];
94	}
95	
96	function updateSquad(id, patch) {
97	  const data = readJson(SQUADS_PATH, { version: 1, squads: {} });
98	  if (!data.squads?.[id]) throw new Error(`Squad "${id}" not found`);
99	  const allowed = ['label', 'description', 'color', 'emoji', 'members'];
100	  const next = { ...data.squads[id] };
101	  for (const k of allowed) {
102	    if (patch[k] !== undefined) next[k] = patch[k];
103	  }
104	  data.squads[id] = next;
105	  data.updatedAt = new Date().toISOString();
106	  atomicWrite(SQUADS_PATH, data);
107	  invalidate();
108	  return next;
109	}
110	
111	function deleteSquad(id, agentList = []) {
112	  const data = readJson(SQUADS_PATH, { version: 1, squads: {} });
113	  if (!data.squads?.[id]) throw new Error(`Squad "${id}" not found`);
114	  const inUse = agentList.filter(a => a.squad === id);
115	  if (inUse.length > 0) {
116	    const ids = inUse.map(a => a.id).join(', ');
117	    throw new Error(`Cannot delete: ${inUse.length} agent(s) still in this squad (${ids})`);
118	  }
119	  delete data.squads[id];
120	  data.updatedAt = new Date().toISOString();
121	  atomicWrite(SQUADS_PATH, data);
122	  invalidate();
123	  return { ok: true, deleted: id };
124	}
125	
126	// ── Tags ───────────────────────────────────────────────────────────────────
127	
128	function addTag(category, tag, info = {}) {
129	  if (!category || !tag) throw new Error('Category and tag required');
130	  const tagId = tag.trim().toLowerCase().replace(/[^a-z0-9-]/g, '-');
131	  if (!tagId) throw new Error('Invalid tag id');
132	  const data = readJson(TAGS_PATH, { version: 1, categories: {} });
133	  data.categories = data.categories || {};
134	  if (!data.categories[category]) {
135	    throw new Error(`Category "${category}" does not exist. Existing: ${Object.keys(data.categories).join(', ')}`);
136	  }
137	  data.categories[category].tags = data.categories[category].tags || {};
138	  if (data.categories[category].tags[tagId]) {
139	    throw new Error(`Tag "${tagId}" already exists in "${category}"`);
140	  }
141	  data.categories[category].tags[tagId] = {
142	    label: info.label || tagId,
143	    description: info.description || '',
144	  };
145	  data.updatedAt = new Date().toISOString();
146	  atomicWrite(TAGS_PATH, data);
147	  invalidate();
148	  return { category, tag: tagId, info: data.categories[category].tags[tagId] };
149	}
150	
151	function deleteTag(category, tag, agentList = []) {
152	  const data = readJson(TAGS_PATH, { version: 1, categories: {} });
153	  if (!data.categories?.[category]?.tags?.[tag]) {
154	    throw new Error(`Tag "${tag}" not found in "${category}"`);
155	  }
156	  const inUse = agentList.filter(a => (a.tags?.[category] || []).includes(tag));
157	  if (inUse.length > 0) {
158	    const ids = inUse.slice(0, 5).map(a => a.id).join(', ');
159	    throw new Error(`Cannot delete: ${inUse.length} agent(s) still tagged (${ids}${inUse.length > 5 ? '...' : ''})`);
160	  }
161	  delete data.categories[category].tags[tag];
162	  data.updatedAt = new Date().toISOString();
163	  atomicWrite(TAGS_PATH, data);
164	  invalidate();
165	  return { ok: true, deleted: { category, tag } };
166	}
167	
168	module.exports = {
169	  loadSquads,
170	  loadTags,
171	  listSquads,
172	  listTagCategories,
173	  getTaxonomy,
174	  addSquad,
175	  updateSquad,
176	  deleteSquad,
177	  addTag,
178	  deleteTag,
179	  invalidate,
180	};
