147	// POST /api/org/agents/bulk — apply same patch to many agents (single batch)
148	router.post('/org/agents/bulk', rateLimit('write'), (req, res) => {
149	  try {
150	    const { agentIds, patch } = req.body || {};
151	    if (!Array.isArray(agentIds) || agentIds.length === 0) {
152	      return res.status(400).json({ error: 'agentIds must be a non-empty array' });
153	    }
154	    const cleanPatch = Object.fromEntries(
155	      Object.entries(patch || {}).filter(([k]) => ALLOWED_PATCH_FIELDS.includes(k))
156	    );
157	    if (Object.keys(cleanPatch).length === 0) {
158	      return res.status(400).json({ error: 'No valid fields in patch' });
159	    }
160	    const batchId = `b_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
161	    const updated = [];
162	    for (const id of agentIds) {
163	      try {
164	        const saved = org.upsertAgent(id, cleanPatch, { action: 'bulk-patch', batchId });
165	        updated.push({ id, ok: true, agent: saved });
166	      } catch (err) {
167	        updated.push({ id, ok: false, error: err.message });
168	      }
169	    }
170	    res.json({ ok: true, batchId, updated });
171	  } catch (err) {
172	    res.status(500).json({ error: err.message });
173	  }
174	});
