176	// POST /api/org/undo/:historyId — reverse a single registry change
177	router.post('/org/undo/:historyId', rateLimit('write'), (req, res) => {
178	  try {
179	    const h = db.getHistory(parseInt(req.params.historyId, 10));
180	    if (!h) return res.status(404).json({ error: 'History entry not found' });
181	    if (h.undone) return res.status(409).json({ error: 'Already undone' });
182	    if (!h.prior_state) return res.status(400).json({ error: 'No prior state to restore' });
183	
184	    // Compute reverse patch: only fields that changed in the original patch
185	    const reversePatch = {};
186	    if (h.patch) {
187	      for (const k of Object.keys(h.patch)) {
188	        reversePatch[k] = h.prior_state[k] ?? null;
189	      }
190	    }
191	    // Apply reverse without writing a new history row; mark original as undone
192	    org.upsertAgent(h.agent_id, reversePatch, { action: 'undo', skipHistory: true });
193	    db.markHistoryUndone(h.id);
194	    res.json({ ok: true, restored: reversePatch, agentId: h.agent_id });
195	  } catch (err) {
196	    res.status(500).json({ error: err.message });
197	  }
198	});
