200	// POST /api/org/undo-batch/:batchId — reverse every change in a bulk batch
201	router.post('/org/undo-batch/:batchId', rateLimit('write'), (req, res) => {
202	  try {
203	    const rows = db.listBatchHistory(req.params.batchId);
204	    if (!rows.length) return res.status(404).json({ error: 'Batch not found' });
205	    const reversed = [];
206	    for (const h of rows) {
207	      if (h.undone || !h.prior_state) continue;
208	      const reversePatch = {};
209	      if (h.patch) {
210	        for (const k of Object.keys(h.patch)) {
211	          reversePatch[k] = h.prior_state[k] ?? null;
212	        }
213	      }
214	      org.upsertAgent(h.agent_id, reversePatch, { action: 'undo-batch', skipHistory: true });
215	      db.markHistoryUndone(h.id);
216	      reversed.push(h.agent_id);
217	    }
218	    res.json({ ok: true, reversed, count: reversed.length });
219	  } catch (err) {
220	    res.status(500).json({ error: err.message });
221	  }
222	});
