53	let _cache: TaxonomyData | null = null
54	const _listeners = new Set<(d: TaxonomyData) => void>()
55	let _inflight: Promise<TaxonomyData> | null = null
56	
57	async function fetchAndBroadcast() {
58	  if (_inflight) return _inflight
59	  _inflight = getTaxonomy()
60	    .then(data => {
61	      _cache = data
62	      _listeners.forEach(fn => fn(data))
63	      return data
64	    })
65	    .catch(() => {
66	      const fb = fallback()
67	      _cache = fb
68	      _listeners.forEach(fn => fn(fb))
69	      return fb
70	    })
71	    .finally(() => { _inflight = null })
72	  return _inflight
73	}
74	
75	export function useTaxonomy(): UseTaxonomyResult {
76	  const [data, setData] = useState<TaxonomyData>(() => _cache || fallback())
77	  const [loading, setLoading] = useState(!_cache)
78	
79	  useEffect(() => {
80	    const onChange = (d: TaxonomyData) => { setData(d); setLoading(false) }
81	    _listeners.add(onChange)
82	    if (!_cache) {
83	      fetchAndBroadcast().finally(() => setLoading(false))
84	    } else {
85	      setLoading(false)
86	    }
87	    return () => { _listeners.delete(onChange) }
88	  }, [])
89	
90	  // Subscribe to SSE so any taxonomy:update across pages auto-refetches
91	  useEffect(() => {
92	    const es = subscribeOrgChart((ev) => {
93	      if (ev.type === 'taxonomy:update') {
94	        fetchAndBroadcast()
95	      }
96	    })
97	    return () => es.close()
98	  }, [])
99	
100	  const refetch = useCallback(() => { fetchAndBroadcast() }, [])
101	
102	  const squadById = Object.fromEntries(data.squads.map(s => [s.id, s]))
103	  const tagsIn = useCallback(
104	    (category: string) => Object.keys(data.categories?.[category]?.tags || {}),
105	    [data]
106	  )
107	
108	  return {
109	    squads: data.squads,
110	    squadById,
111	    categories: data.categories,
112	    tagsIn,
113	    loading,
114	    refetch,
115	  }
116	}
